DAYS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]


def _is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


def _ordinal(s):
    y, m, d = map(int, s.split('-'))
    # Count leaps by elapsed whole years so 0000-03-01..0000-12-31 is day 0's neighbourhood;
    # only differences of ordinals are used, so the constant offset is irrelevant.
    leaps = (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
    return y * 365 + leaps + sum(DAYS[: m - 1]) + d + (_is_leap(y) and m > 2)


def days_between(a, b):
    return _ordinal(b) - _ordinal(a)
